class Solution {
public:
    int addDigits(int num) {
        if(num<10){
            return num;
        }
        int n = num;
        int digi_sum = 0;
        while(n > 9){
            while(n!=0){
                int digit = n%10;
                digi_sum += digit;
                n = n/10;
            }
            if(digi_sum > 9){
                n = digi_sum;
                digi_sum = 0;
            }
        }
        return digi_sum;
    }
};

